-- 073_rg6_swap_v4_into_public.sql -- Phase RG.6: make the v4 reference-genome tables the schema of
-- record, by moving them into public and the old flat tables out.
--
-- Plan: docs/ref_genomes_rg6_plan.md (gate G1-G7; R.6 ran first, 072). Generated by gen_073.py from
-- live definitions on 2026-11-02; the function rewrites below are guarded by the md5 of the bodies
-- they replace.
--
-- What it does, in one transaction:
--   1. final sync public -> v4 (sync_ref_assembly, sync_ref_read_qc, sync_ref_submission), then
--      requires every check_ref_*() check that is not a note to be 0;
--   2. requires the objects it moves and drops to be exactly the ones listed below;
--   3. rebuilds public.v_sequencing_run_fk_readiness (R.6) on hifi_read_qc / hic_read_qc, since it
--      read the two tables this archives;
--   4. drops the window-only objects: the six sync_ref_* / check_ref_* functions and the seven
--      sync_* source views;
--   5. moves the six old tables (ref_genomes, ref_genomes_assembly_uploads, ref_genomes_sra_uploads,
--      raw_qc, hifi_reads_qc, hic_reads_qc), the two old views over them (coverage_summary,
--      goat_species_v1), and v4's window tables ref_key_map and ref_excluded_rows into a new
--      pre_v4_archive (kept until RG.7). pre_v2_archive.goat_species_v1_pre_v2 follows
--      ref_genomes there by OID, an archive reading an archive;
--   6. moves the other 23 v4 tables, the 14 compatibility and status views, and the 6 functions
--      that outlive the window into public;
--   7. rewrites the function bodies that named v4. (070's two haplotype triggers, 071's
--      exclusivity trigger) and gives resolve_sra_upload_runs() search_path public;
--   8. corrects the comments that described the window, and drops schema v4.
--
-- Moving keeps OIDs: views stay bound to what they read, owned sequences, indexes, constraints and
-- triggers follow their tables, and grants travel. The v4 compatibility views already carry the
-- grants the old public objects had (readonly SELECT on all; oceangenom_web SELECT on ref_genomes
-- and ref_genomes_assembly_uploads), asserted below rather than re-granted.
--
-- After this, the six old names are read-only views. A writer that still inserts into them fails
-- on "cannot insert into view"; the phase-rg-v4 writers deploy the same day. OcOm_B219's GCA
-- resolver is left to its maintainer (owner, 2026-11-02).
--
-- Rows not carried: ref_genomes and raw_qc keep 4 excluded rows each (ref_excluded_rows) and 3
-- rows under corrected keys (ref_key_map), as the nightly checks have compared since RG.1. The
-- archived tables and both triage tables keep them.
--
-- Not here: FKs from hifi_read_qc.run_id / hic_read_qc.run_id to sequencing_run. All 829 rows
-- satisfy them, but since 072 nothing adds new runs to sequencing_run, so the FK would refuse the
-- Hi-C yield of a run the workbook has not reached yet. Left to R.7, with sequencing.run_id.
--
-- Opt-in, because it changes what production writers can write:
--     PGOPTIONS="-c oceanomics.rg6_swap=go" bin/apply_migrations.py
-- Replay: when v4 is gone and public.ref_assembly exists, the file does nothing.
--
-- Remove the 19:00 UTC sync_v4.sh cron line the same day.
--
-- Revert: sql/revert/073_rg6_swap_v4_into_public_revert.sql.

BEGIN;

DO $rg6$
DECLARE
  old_tables    text[] := ARRAY['hic_reads_qc', 'hifi_reads_qc', 'raw_qc', 'ref_genomes', 'ref_genomes_assembly_uploads', 'ref_genomes_sra_uploads'];
  old_views     text[] := ARRAY['coverage_summary', 'goat_species_v1'];
  v4_tables     text[] := ARRAY['hic_read_qc', 'hifi_read_qc', 'ref_assembly', 'ref_assembly_part', 'ref_assembly_run', 'ref_busco', 'ref_chromosome_stats', 'ref_excluded_rows', 'ref_genomescope', 'ref_gfastats', 'ref_hifi_adapter_filter', 'ref_key_map', 'ref_merqury_completeness', 'ref_merqury_qv', 'ref_omnic', 'ref_read_set', 'ref_read_set_external', 'ref_read_set_run', 'ref_seqkit_stats', 'ref_sra_upload', 'ref_sra_upload_run', 'ref_sra_upload_unlinked', 'ref_stage', 'ref_submission', 'ref_submission_haplotype'];
  archived_v4   text[] := ARRAY['ref_excluded_rows', 'ref_key_map'];
  moved_tables  text[] := ARRAY['hic_read_qc', 'hifi_read_qc', 'ref_assembly', 'ref_assembly_part', 'ref_assembly_run', 'ref_busco', 'ref_chromosome_stats', 'ref_genomescope', 'ref_gfastats', 'ref_hifi_adapter_filter', 'ref_merqury_completeness', 'ref_merqury_qv', 'ref_omnic', 'ref_read_set', 'ref_read_set_external', 'ref_read_set_run', 'ref_seqkit_stats', 'ref_sra_upload', 'ref_sra_upload_run', 'ref_sra_upload_unlinked', 'ref_stage', 'ref_submission', 'ref_submission_haplotype'];
  moved_views   text[] := ARRAY['coverage_summary', 'goat_species_v1', 'hic_reads_qc', 'hifi_reads_qc', 'raw_qc', 'ref_genomes', 'ref_genomes_assembly_uploads', 'ref_genomes_sra_uploads', 'v_read_qc_sequencing_readiness', 'v_read_set_run_readiness', 'v_ref_assembly_run_readiness', 'v_ref_assembly_status', 'v_ref_assembly_summary', 'v_sra_upload_run_readiness'];
  sync_views    text[] := ARRAY['sync_raw_qc_source', 'sync_read_qc_hic_source', 'sync_read_qc_hifi_source', 'sync_read_set_source', 'sync_ref_genomes_source', 'sync_ref_sra_source', 'sync_ref_submission_source'];
  sync_views_drop text[] := ARRAY['sync_read_set_source', 'sync_ref_sra_source', 'sync_raw_qc_source', 'sync_read_qc_hic_source', 'sync_read_qc_hifi_source', 'sync_ref_genomes_source', 'sync_ref_submission_source'];  -- readers before what they read
  window_fns    text[] := ARRAY['check_ref_assembly', 'check_ref_read_qc', 'check_ref_submission', 'sync_ref_assembly', 'sync_ref_read_qc', 'sync_ref_submission'];
  kept_fns      text[] := ARRAY['ref_assembly_run_genomic_only', 'ref_read_set_external_exclusive', 'ref_read_set_run_pacbio_only', 'ref_submission_assembly_to_haplotypes', 'ref_submission_haplotype_assembly', 'resolve_sra_upload_runs'];
  have text[];
  obj  text;
  n    bigint;
  r    record;
  old_n jsonb := '{}';
BEGIN
  -- Replay.
  IF to_regnamespace('v4') IS NULL AND to_regclass('public.ref_assembly') IS NOT NULL THEN
    RAISE NOTICE '073: already swapped (no v4, public.ref_assembly exists); nothing to do';
    RETURN;
  END IF;

  IF coalesce(current_setting('oceanomics.rg6_swap', true), '') <> 'go' THEN
    RAISE EXCEPTION 'This moves v4 into public and turns ref_genomes, raw_qc and four more tables into '
      'views. Run with PGOPTIONS="-c oceanomics.rg6_swap=go"';
  END IF;
  IF to_regnamespace('v3') IS NOT NULL THEN
    RAISE EXCEPTION '073: v3 still exists; R.6 (072) runs first (gate G5)';
  END IF;

  -- 1. Final sync, then the checks.
  PERFORM * FROM v4.sync_ref_assembly();
  PERFORM * FROM v4.sync_ref_read_qc();
  PERFORM * FROM v4.sync_ref_submission();
  FOR r IN SELECT 'assembly' AS side, * FROM v4.check_ref_assembly()
           UNION ALL SELECT 'read_qc', * FROM v4.check_ref_read_qc()
           UNION ALL SELECT 'submission', * FROM v4.check_ref_submission() LOOP
    IF r.problems <> 0 AND r.check_name NOT LIKE 'note:%' THEN
      RAISE EXCEPTION '073: %: % problem(s) in "%" after the final sync', r.side, r.problems, r.check_name;
    END IF;
  END LOOP;
  -- What each old name will show: its v4 compatibility view today.
  FOREACH obj IN ARRAY old_tables LOOP
    EXECUTE format('SELECT count(*) FROM v4.%I', obj) INTO n;
    old_n := old_n || jsonb_build_object(obj, n);
  END LOOP;

  -- 2. Exactly the expected objects.
  SELECT array_agg(relname::text ORDER BY relname) INTO have FROM pg_class
   WHERE relnamespace = 'v4'::regnamespace AND relkind IN ('r','p');
  IF have IS DISTINCT FROM (SELECT array_agg(x ORDER BY x) FROM unnest(v4_tables) x) THEN
    RAISE EXCEPTION '073: v4 tables are %, expected %', have, v4_tables;
  END IF;
  SELECT array_agg(relname::text ORDER BY relname) INTO have FROM pg_class
   WHERE relnamespace = 'v4'::regnamespace AND relkind IN ('v','m');
  IF have IS DISTINCT FROM (SELECT array_agg(x ORDER BY x) FROM unnest(moved_views || sync_views) x) THEN
    RAISE EXCEPTION '073: v4 views are %, expected %', have, moved_views || sync_views;
  END IF;
  SELECT array_agg(proname::text ORDER BY proname) INTO have FROM pg_proc WHERE pronamespace = 'v4'::regnamespace;
  IF have IS DISTINCT FROM (SELECT array_agg(x ORDER BY x) FROM unnest(window_fns || kept_fns) x) THEN
    RAISE EXCEPTION '073: v4 functions are %, expected %', have, window_fns || kept_fns;
  END IF;
  SELECT array_agg(relname::text ORDER BY relname) INTO have FROM pg_class
   WHERE relnamespace = 'public'::regnamespace AND relname = ANY (old_tables) AND relkind = 'r';
  IF have IS DISTINCT FROM (SELECT array_agg(x ORDER BY x) FROM unnest(old_tables) x) THEN
    RAISE EXCEPTION '073: the old public tables are %, expected %', have, old_tables;
  END IF;
  SELECT array_agg(DISTINCT n2.nspname || '.' || dv.relname ORDER BY n2.nspname || '.' || dv.relname) INTO have
    FROM pg_depend d JOIN pg_rewrite rw ON rw.oid = d.objid
    JOIN pg_class dv ON dv.oid = rw.ev_class JOIN pg_namespace n2 ON n2.oid = dv.relnamespace
    JOIN pg_class t ON t.oid = d.refobjid
   WHERE t.relnamespace = 'public'::regnamespace AND t.relname = ANY (old_tables || old_views) AND dv.oid <> t.oid;
  IF have IS DISTINCT FROM ARRAY['pre_v2_archive.goat_species_v1_pre_v2', 'public.coverage_summary',
       'public.goat_species_v1', 'public.v_sequencing_run_fk_readiness', 'v4.sync_raw_qc_source',
       'v4.sync_read_qc_hic_source', 'v4.sync_read_qc_hifi_source', 'v4.sync_ref_genomes_source',
       'v4.sync_ref_sra_source', 'v4.sync_ref_submission_source'] THEN
    RAISE EXCEPTION '073: views reading the old objects are %, expected the ones this file handles', have;
  END IF;
  SELECT array_agg(conname::text ORDER BY conname) INTO have FROM pg_constraint c
   WHERE contype = 'f' AND (confrelid IN (SELECT oid FROM pg_class WHERE relnamespace = 'public'::regnamespace AND relname = ANY (old_tables))
                         OR conrelid IN (SELECT oid FROM pg_class WHERE relnamespace = 'public'::regnamespace AND relname = ANY (old_tables)));
  IF have IS DISTINCT FROM ARRAY['ref_genomes_sra_runs_og_id_fkey'] THEN
    RAISE EXCEPTION '073: FKs touching the old tables are %, expected the one between two of them', have;
  END IF;
  SELECT count(*) INTO n FROM pg_class c
   WHERE c.relnamespace = 'public'::regnamespace AND c.relname IN (SELECT relname FROM pg_class
           WHERE relnamespace = 'v4'::regnamespace AND relname <> ALL (sync_views || archived_v4))
     AND c.relname <> ALL (old_tables || old_views);
  IF n <> 0 THEN
    RAISE EXCEPTION '073: % public relation(s) already carry a name v4 brings', n;
  END IF;
  -- Grants: every SELECT grantee of an old public object has SELECT on the v4 object of that name.
  SELECT count(*) INTO n FROM information_schema.role_table_grants o
   WHERE o.table_schema = 'public' AND o.table_name = ANY (old_tables || old_views) AND o.privilege_type = 'SELECT'
     AND NOT EXISTS (SELECT 1 FROM information_schema.role_table_grants v
                      WHERE v.table_schema = 'v4' AND v.table_name = o.table_name
                        AND v.grantee = o.grantee AND v.privilege_type = 'SELECT');
  IF n <> 0 THEN
    RAISE EXCEPTION '073: % SELECT grant(s) on the old objects are missing from their v4 replacements', n;
  END IF;
  IF (SELECT md5(prosrc) FROM pg_proc WHERE pronamespace = 'v4'::regnamespace AND proname = 'ref_assembly_run_genomic_only') <> '7f6c9077b2bfa0b24dc73748ab97c290' THEN
    RAISE EXCEPTION '073: v4.ref_assembly_run_genomic_only() changed since 073 was generated; regenerate it';
  END IF;
  IF (SELECT md5(prosrc) FROM pg_proc WHERE pronamespace = 'v4'::regnamespace AND proname = 'ref_read_set_external_exclusive') <> 'f82716860f2fc4e2ddaca538b6f589a6' THEN
    RAISE EXCEPTION '073: v4.ref_read_set_external_exclusive() changed since 073 was generated; regenerate it';
  END IF;
  IF (SELECT md5(prosrc) FROM pg_proc WHERE pronamespace = 'v4'::regnamespace AND proname = 'ref_read_set_run_pacbio_only') <> '0207d56fddf5877f0e20d2a9d48bc0cd' THEN
    RAISE EXCEPTION '073: v4.ref_read_set_run_pacbio_only() changed since 073 was generated; regenerate it';
  END IF;
  IF (SELECT md5(prosrc) FROM pg_proc WHERE pronamespace = 'v4'::regnamespace AND proname = 'ref_submission_assembly_to_haplotypes') <> '7ee4aa1d571d8ffe62289b680abb6ddb' THEN
    RAISE EXCEPTION '073: v4.ref_submission_assembly_to_haplotypes() changed since 073 was generated; regenerate it';
  END IF;
  IF (SELECT md5(prosrc) FROM pg_proc WHERE pronamespace = 'v4'::regnamespace AND proname = 'ref_submission_haplotype_assembly') <> '94919442dc4cb4328bfb24d7981421fe' THEN
    RAISE EXCEPTION '073: v4.ref_submission_haplotype_assembly() changed since 073 was generated; regenerate it';
  END IF;
  IF (SELECT md5(prosrc) FROM pg_proc WHERE pronamespace = 'v4'::regnamespace AND proname = 'resolve_sra_upload_runs') <> 'b774edd5ad739f54049d0082e47a65b8' THEN
    RAISE EXCEPTION '073: v4.resolve_sra_upload_runs() changed since 073 was generated; regenerate it';
  END IF;

  -- 3. R.6's run-FK readiness view, onto the new read-QC tables.
  EXECUTE $fkr$CREATE OR REPLACE VIEW public.v_sequencing_run_fk_readiness AS  SELECT 'sequencing'::text AS child,
    count(*) AS child_rows,
    count(*) FILTER (WHERE ((c.run_id IS NOT NULL) AND (r.run_id IS NULL))) AS failing_rows,
    string_agg(DISTINCT c.run_id, ', '::text) FILTER (WHERE ((c.run_id IS NOT NULL) AND (r.run_id IS NULL))) AS failing_run_ids
   FROM (public.sequencing c
     LEFT JOIN public.sequencing_run r ON ((r.run_id = c.run_id)))
UNION ALL
 SELECT 'raw_data'::text AS child,
    count(*) AS child_rows,
    count(*) FILTER (WHERE ((c.run_id IS NOT NULL) AND (r.run_id IS NULL))) AS failing_rows,
    string_agg(DISTINCT c.run_id, ', '::text) FILTER (WHERE ((c.run_id IS NOT NULL) AND (r.run_id IS NULL))) AS failing_run_ids
   FROM (public.raw_data c
     LEFT JOIN public.sequencing_run r ON ((r.run_id = c.run_id)))
UNION ALL
 SELECT 'hifi_read_qc'::text AS child,
    count(*) AS child_rows,
    count(*) FILTER (WHERE ((c.run_id IS NOT NULL) AND (r.run_id IS NULL))) AS failing_rows,
    string_agg(DISTINCT c.run_id, ', '::text) FILTER (WHERE ((c.run_id IS NOT NULL) AND (r.run_id IS NULL))) AS failing_run_ids
   FROM (v4.hifi_read_qc c
     LEFT JOIN public.sequencing_run r ON ((r.run_id = c.run_id)))
UNION ALL
 SELECT 'hic_read_qc'::text AS child,
    count(*) AS child_rows,
    count(*) FILTER (WHERE ((c.run_id IS NOT NULL) AND (r.run_id IS NULL))) AS failing_rows,
    string_agg(DISTINCT c.run_id, ', '::text) FILTER (WHERE ((c.run_id IS NOT NULL) AND (r.run_id IS NULL))) AS failing_run_ids
   FROM (v4.hic_read_qc c
     LEFT JOIN public.sequencing_run r ON ((r.run_id = c.run_id)));$fkr$;

  -- 4. Window-only objects.
  FOREACH obj IN ARRAY sync_views_drop LOOP
    EXECUTE format('DROP VIEW v4.%I', obj);
  END LOOP;
  FOR r IN SELECT p.oid::regprocedure AS fn FROM pg_proc p
            WHERE p.pronamespace = 'v4'::regnamespace AND p.proname = ANY (window_fns) LOOP
    EXECUTE format('DROP FUNCTION %s', r.fn);
  END LOOP;

  -- 5. The old objects and the window tables, kept until RG.7.
  CREATE SCHEMA pre_v4_archive;
  COMMENT ON SCHEMA pre_v4_archive IS
    'Phase RG archive: the six public tables and two views RG.6 (073) replaced, and v4''s window tables '
    'ref_key_map and ref_excluded_rows. Read-only history. Dropped at RG.7 after a pg_dump. '
    'docs/ref_genomes_rg6_plan.md';
  FOREACH obj IN ARRAY old_views LOOP
    EXECUTE format('ALTER VIEW public.%I SET SCHEMA pre_v4_archive', obj);
  END LOOP;
  FOREACH obj IN ARRAY old_tables LOOP
    EXECUTE format('ALTER TABLE public.%I SET SCHEMA pre_v4_archive', obj);
  END LOOP;
  FOREACH obj IN ARRAY archived_v4 LOOP
    EXECUTE format('ALTER TABLE v4.%I SET SCHEMA pre_v4_archive', obj);
  END LOOP;
  COMMENT ON TABLE pre_v4_archive.ref_genomes IS 'public.ref_genomes before RG.6 (archived by 073, 2026-11-02). Read-only history; public.ref_genomes is now a view over ref_assembly and the per-tool tables. Dropped in RG.7.';
  COMMENT ON TABLE pre_v4_archive.ref_genomes_assembly_uploads IS 'public.ref_genomes_assembly_uploads before RG.6 (archived by 073, 2026-11-02). Read-only history; now a view over ref_submission and ref_submission_haplotype. Dropped in RG.7.';
  COMMENT ON TABLE pre_v4_archive.ref_genomes_sra_uploads IS 'public.ref_genomes_sra_uploads before RG.6 (archived by 073, 2026-11-02). Read-only history; now a view over ref_sra_upload. Dropped in RG.7.';
  COMMENT ON TABLE pre_v4_archive.raw_qc IS 'public.raw_qc before RG.6 (archived by 073, 2026-11-02). Read-only history; now a view over ref_read_set, ref_genomescope and ref_hifi_adapter_filter. Dropped in RG.7.';
  COMMENT ON TABLE pre_v4_archive.hifi_reads_qc IS 'public.hifi_reads_qc before RG.6 (archived by 073, 2026-11-02). Read-only history; now a view over hifi_read_qc. Dropped in RG.7.';
  COMMENT ON TABLE pre_v4_archive.hic_reads_qc IS 'public.hic_reads_qc before RG.6 (archived by 073, 2026-11-02). Read-only history; now a view over hic_read_qc. Dropped in RG.7.';
  COMMENT ON TABLE pre_v4_archive.ref_key_map IS 'Phase RG window: public assembly keys that v4 carried under a corrected key (archived by 073 at RG.6). Read-only history. Dropped in RG.7.';
  COMMENT ON TABLE pre_v4_archive.ref_excluded_rows IS 'Phase RG window: public rows that v4 did not carry, and why (archived by 073 at RG.6). Read-only history. Dropped in RG.7.';

  -- 6. Everything else into public.
  FOREACH obj IN ARRAY moved_tables LOOP
    EXECUTE format('ALTER TABLE v4.%I SET SCHEMA public', obj);
  END LOOP;
  FOREACH obj IN ARRAY moved_views LOOP
    EXECUTE format('ALTER VIEW v4.%I SET SCHEMA public', obj);
  END LOOP;
  FOR r IN SELECT p.oid::regprocedure AS fn FROM pg_proc p
            WHERE p.pronamespace = 'v4'::regnamespace AND p.proname = ANY (kept_fns) LOOP
    EXECUTE format('ALTER FUNCTION %s SET SCHEMA public', r.fn);
  END LOOP;

  -- 7. Bodies that named v4., and the resolver's search_path.
  EXECUTE $def0$CREATE OR REPLACE FUNCTION public.ref_read_set_external_exclusive()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
  IF TG_TABLE_NAME = 'ref_read_set_run' THEN
    IF EXISTS (SELECT 1 FROM public.ref_read_set_external x WHERE x.read_set_id = NEW.read_set_id) THEN
      RAISE EXCEPTION 'ref_read_set_run: read set % is external (ref_read_set_external); it has no sequencing rows',
        NEW.read_set_id;
    END IF;
  ELSIF EXISTS (SELECT 1 FROM public.ref_read_set_run r WHERE r.read_set_id = NEW.read_set_id) THEN
    RAISE EXCEPTION 'ref_read_set_external: read set % has sequencing rows (ref_read_set_run); it is not external',
      NEW.read_set_id;
  END IF;
  RETURN NEW;
END
$function$
$def0$;
  EXECUTE $def1$CREATE OR REPLACE FUNCTION public.ref_submission_assembly_to_haplotypes()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
  UPDATE public.ref_submission_haplotype h SET assembly_id = NEW.assembly_id
  WHERE h.submission_id = NEW.submission_id AND h.assembly_id IS DISTINCT FROM NEW.assembly_id;
  RETURN NULL;
END
$function$
$def1$;
  EXECUTE $def2$CREATE OR REPLACE FUNCTION public.ref_submission_haplotype_assembly()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
  SELECT s.assembly_id INTO NEW.assembly_id FROM public.ref_submission s WHERE s.submission_id = NEW.submission_id;
  RETURN NEW;
END
$function$
$def2$;
  EXECUTE $def3$CREATE OR REPLACE FUNCTION public.resolve_sra_upload_runs(p_og_id text, p_data_type text, p_filenames text)
 RETURNS SETOF text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  -- File names call a tube's first Hi-C library HICL1; the workbook calls it HICL (065).
  files text[] := ARRAY(SELECT regexp_replace(btrim(f), '_HICL1(?=[_.])', '_HICL', 'g')
                        FROM unnest(string_to_array(coalesce(p_filenames, ''), ',')) f
                        WHERE btrim(f) <> '');
  kind  text;
  runs  text[];
  hit   text[];
BEGIN
  IF cardinality(files) = 0 OR p_og_id IS NULL THEN
    RETURN;
  END IF;

  IF p_data_type = 'hifi' THEN
    RETURN QUERY
    WITH f AS (
      SELECT substring(x from 'm[0-9]+[a-z]?_([0-9]{6})_[0-9]{6}') AS mdate,
             substring(x from '\.(bc[0-9]+)(?:--bc[0-9]+)?\.') AS bc
      FROM unnest(files) x
    ), ub AS (
      SELECT CASE WHEN count(DISTINCT bc) = 1 THEN min(bc) END AS bc FROM f
    ), mv AS (
      SELECT DISTINCT f.mdate, coalesce(f.bc, ub.bc) AS bc FROM f CROSS JOIN ub WHERE f.mdate IS NOT NULL
    ), cand AS (
      SELECT mv.mdate, mv.bc, s.sequencing_id, s.library_tube_id,
             abs(to_date(mv.mdate, 'YYMMDD') - to_date(s.seq_date, 'YYMMDD')) AS gap
      FROM mv JOIN v_sequencing_browse s
        ON s.og_id = p_og_id AND s.technology IN ('PacBio HIFI', 'PacBio') AND s.library_type = 'pacbio'
       AND s.seq_date ~ '^[0-9]{6}$' AND s.status IS DISTINCT FROM 'Failed'
       AND abs(to_date(mv.mdate, 'YYMMDD') - to_date(s.seq_date, 'YYMMDD')) <= 21
    ), nearest AS (
      SELECT c.* FROM cand c
      WHERE c.gap = (SELECT min(c2.gap) FROM cand c2 WHERE c2.mdate = c.mdate AND c2.bc IS NOT DISTINCT FROM c.bc)
    ), narrowed AS (
      SELECT n.mdate, n.bc, n.sequencing_id FROM nearest n
      WHERE (SELECT count(*) FROM nearest n2 WHERE n2.mdate = n.mdate AND n2.bc IS NOT DISTINCT FROM n.bc) = 1
         OR EXISTS (SELECT 1 FROM hifi_read_qc q
                    WHERE q.og_id = p_og_id AND q.barcode = n.bc
                      AND (q.sequencing_id = n.sequencing_id
                           OR q.og_id || q.tissue || '_' || q.ext_type || '_' || q.lib_code = n.library_tube_id))
    ), one AS (
      SELECT mdate, bc FROM narrowed GROUP BY mdate, bc HAVING count(*) = 1
    )
    SELECT DISTINCT n.sequencing_id FROM narrowed n
    JOIN one o ON o.mdate = n.mdate AND o.bc IS NOT DISTINCT FROM n.bc;
    RETURN;
  END IF;

  kind := CASE p_data_type WHEN 'hic' THEN 'Hi-C' WHEN 'ont' THEN 'ONT' WHEN 'illumina' THEN 'Illumina' END;
  IF kind IS NULL THEN
    RETURN;
  END IF;
  runs := ARRAY(SELECT DISTINCT m[1] FROM unnest(files) x,
                regexp_matches(x, '(?:^|[._])((?:NOVA|NEXT|ISEQ|PACB|ONT)[A-Za-z-]*_[0-9]{6}_[A-Za-z0-9]+)(?=[._])', 'g') m);
  IF cardinality(runs) = 0 THEN
    RETURN;
  END IF;
  hit := ARRAY(SELECT s.sequencing_id FROM v_sequencing_browse s
               WHERE s.og_id = p_og_id AND s.technology = kind AND s.run_id = ANY (runs) AND s.status IS DISTINCT FROM 'Failed'
                 AND EXISTS (SELECT 1 FROM unnest(files) x
                             WHERE strpos(x, s.library_tube_id || '_') > 0 OR strpos(x, s.library_tube_id || '.') > 0));
  IF cardinality(hit) = 0 THEN
    hit := ARRAY(SELECT s.sequencing_id FROM v_sequencing_browse s
                 WHERE s.og_id = p_og_id AND s.technology = kind AND s.run_id = ANY (runs) AND s.status IS DISTINCT FROM 'Failed');
  END IF;
  IF cardinality(hit) = 0 THEN
    hit := ARRAY(SELECT s.sequencing_id FROM v_sequencing_browse s
                 WHERE s.og_id = p_og_id AND s.technology = kind AND s.status IS DISTINCT FROM 'Failed'
                   AND split_part(s.run_id, '_', 2) = ANY (ARRAY(SELECT split_part(r, '_', 2) FROM unnest(runs) r)));
  END IF;
  IF cardinality(hit) = 1 OR EXISTS (SELECT 1 FROM unnest(files) x, v_sequencing_browse s
                                     WHERE s.sequencing_id = ANY (hit)
                                       AND (strpos(x, s.library_tube_id || '_') > 0 OR strpos(x, s.library_tube_id || '.') > 0)) THEN
    RETURN QUERY SELECT unnest(hit);
  END IF;
END
$function$
$def3$;

  -- 8. Comments, then schema v4.
  COMMENT ON VIEW public.coverage_summary IS 'Coverage per OG from raw_qc, hifi_reads_qc and hic_reads_qc (the compatibility views). Replaced the public view of the same name at RG.6 (073); the old one is in pre_v4_archive.';
  COMMENT ON VIEW public.goat_species_v1 IS 'GoaT species submission view; in_assembly from ref_assembly. Replaced the public view of the same name at RG.6 (073); the old one is in pre_v4_archive.';
  COMMENT ON TABLE public.hic_read_qc IS 'Illumina run statistics for Hi-C libraries, per library per run per lane. Writer: ref_genomes_hic_automation push_hic_yield.py (from poll-hic-multiqc.py). sequencing_id: the one Hi-C sequencing row of this OG and tissue on this run, NULL where none or several match (v_read_qc_sequencing_readiness).';
  COMMENT ON VIEW public.v_read_qc_sequencing_readiness IS 'Read-QC rows with no sequencing link, and why. Fix at source (the workbook); the writers link new rows.';
  COMMENT ON VIEW public.v_ref_assembly_run_readiness IS 'Assemblies with no run link, and the OG''s PacBio/ONT DNA rows to choose from. Their seq_date matches no run date (RG.0 §1.5); the writers link new assemblies.';
  COMMENT ON VIEW public.v_sra_upload_run_readiness IS 'SRA uploads with no sequencing link, and why. Most are run IDs the workbook has wrong (064''s header); fix at source, delete the ref_sra_upload_unlinked row, and insert the links resolve_sra_upload_runs() returns. Since RG.6 no nightly sync does this.';
  COMMENT ON FUNCTION public.resolve_sra_upload_runs(text, text, text) IS 'The sequencing rows an SRA upload''s file names point to (064''s forward rule; HICL1 = HICL, 065; failed runs skipped, 069). Used by ENA-ref-genomes step 09. search_path public since RG.6 (073).';
  COMMENT ON FUNCTION public.ref_read_set_external_exclusive() IS 'A read set is either external or linked to sequencing rows, not both (071).';
  COMMENT ON VIEW public.v_sequencing_run_fk_readiness IS 'For each table R.7 will FK to sequencing_run: rows that would fail today, and their run IDs. The two read-QC rows read hifi_read_qc and hic_read_qc since RG.6 (073).';

  SELECT count(*) INTO n FROM pg_class WHERE relnamespace = 'v4'::regnamespace;
  IF n <> 0 OR EXISTS (SELECT 1 FROM pg_proc WHERE pronamespace = 'v4'::regnamespace) THEN
    RAISE EXCEPTION '073: objects still in v4 after the move: %',
      (SELECT string_agg(relname, ', ') FROM pg_class WHERE relnamespace = 'v4'::regnamespace);
  END IF;
  ALTER DEFAULT PRIVILEGES IN SCHEMA v4 REVOKE SELECT ON TABLES FROM readonly;
  DROP SCHEMA v4 RESTRICT;

  -- Verify.
  SELECT count(*) INTO n
    FROM pg_depend d JOIN pg_rewrite rw ON rw.oid = d.objid
    JOIN pg_class dv ON dv.oid = rw.ev_class JOIN pg_class t ON t.oid = d.refobjid
   WHERE dv.relnamespace = 'public'::regnamespace AND t.relnamespace = 'pre_v4_archive'::regnamespace;
  IF n <> 0 THEN
    RAISE EXCEPTION '073: % public view dependency still points into pre_v4_archive', n;
  END IF;
  SELECT count(*) INTO n FROM pg_proc p
   WHERE p.pronamespace = 'public'::regnamespace
     AND (p.prosrc ~ '\mv4\.' OR array_to_string(p.proconfig, ' ') ~ '\mv4\M');
  IF n <> 0 THEN
    RAISE EXCEPTION '073: % public function(s) still name v4', n;
  END IF;
  FOREACH obj IN ARRAY old_tables LOOP
    IF (SELECT relkind FROM pg_class WHERE oid = format('public.%I', obj)::regclass) <> 'v' THEN
      RAISE EXCEPTION '073: public.% should now be a view', obj;
    END IF;
    EXECUTE format('SELECT count(*) FROM public.%I', obj) INTO n;
    IF n <> (old_n ->> obj)::bigint THEN
      RAISE EXCEPTION '073: public.% has % rows, its v4 view had %', obj, n, old_n ->> obj;
    END IF;
    -- ref_genomes and raw_qc differ from the old tables by the triaged rows (ref_excluded_rows,
    -- ref_key_map), which the checks compared; the other four equal them row for row.
    CONTINUE WHEN obj IN ('ref_genomes', 'raw_qc');
    EXECUTE format('SELECT (SELECT count(*) FROM (SELECT * FROM public.%1$I EXCEPT ALL SELECT * FROM pre_v4_archive.%1$I) x)'
                   ' + (SELECT count(*) FROM (SELECT * FROM pre_v4_archive.%1$I EXCEPT ALL SELECT * FROM public.%1$I) y)', obj) INTO n;
    IF n <> 0 THEN
      RAISE EXCEPTION '073: public.% differs from the archived table in % row(s)', obj, n;
    END IF;
  END LOOP;
  SELECT count(*) INTO n FROM pg_class c
   WHERE c.relnamespace = 'public'::regnamespace AND c.relname = ANY (moved_tables || moved_views)
     AND NOT has_table_privilege('readonly', c.oid, 'SELECT');
  IF n <> 0 THEN
    RAISE EXCEPTION '073: readonly cannot read % moved relation(s)', n;
  END IF;
  IF NOT has_table_privilege('oceangenom_web', 'public.ref_genomes', 'SELECT')
     OR NOT has_table_privilege('oceangenom_web', 'public.ref_genomes_assembly_uploads', 'SELECT') THEN
    RAISE EXCEPTION '073: oceangenom_web lost SELECT on ref_genomes or ref_genomes_assembly_uploads';
  END IF;
  -- An old writer must fail loudly. The sub-block rolls back whatever it did.
  BEGIN
    INSERT INTO public.raw_qc (og_id) VALUES ('OG_073_PROBE');
    RAISE EXCEPTION USING ERRCODE = 'P0073', MESSAGE = 'insert into raw_qc succeeded';
  EXCEPTION
    WHEN SQLSTATE 'P0073' THEN
      RAISE EXCEPTION '073: an insert into the raw_qc view succeeded; old writers would not fail';
    WHEN OTHERS THEN
      NULL;  -- "cannot insert into view": what an old writer will now see
  END;

  RAISE NOTICE '073: swapped. % ; v4 dropped', old_n;
END
$rg6$;

COMMIT;
